template.solver:
def solve(n):
    best = [0]
    def dfs(start, chosen, sums):
        if len(chosen) > best[0]:
            best[0] = len(chosen)
        for x in range(start, n + 1):
            new = [x + c for c in chosen]
            if len(set(new)) == len(new) and not any((s in sums) for s in new):
                dfs(x + 1, chosen + [x], sums | set(new))
    dfs(1, [], set())
    return best[0]
